// Animated logo clips for the demo video, drawn by headless Chrome frame by frame (30 fps, 1920x1080):
//   logo-sting.mp4 (1.0 s): the mark alone; the three legs turn 120° into place and the settlement dot pops in.
//   logo-end.mp4 (4.0 s): the same turn, then the lockup (mark + NOMAD. wordmark), nomad.charlesms.dev, "Built on NEAR Intents".
// The mark's geometry is read from web/public/logo-mark.svg (generated by scripts/logo.mjs), never redrawn.
//   node scripts/demo-logo.mjs [out dir = out/demo]
import { spawn } from "node:child_process";
import { readFileSync, readdirSync, existsSync } from "node:fs";
import { join, resolve, dirname } from "node:path";
import { homedir } from "node:os";

const [outDir = "out/demo"] = process.argv.slice(2);
const root = resolve(dirname(new URL(import.meta.url).pathname), "..");
const svg = readFileSync(join(root, "web/public/logo-mark.svg"), "utf8");
const paths = [...svg.matchAll(/<path d="([^"]+)" fill="([^"]+)"\/>/g)].map((m) => m[1]);
const dotM = svg.match(/<circle cx="([\d.]+)" cy="([\d.]+)" r="([\d.]+)" fill="([^"]+)"/);
const grotesk = readFileSync(join(root, "demo/assets/space-grotesk-latin.woff2")).toString("base64");
const pixel = readFileSync(join(root, "web/node_modules/geist/dist/fonts/geist-pixel/GeistPixel-Grid.woff2")).toString("base64");
const FFMPEG = process.env.FFMPEG ?? "ffmpeg";

const pw = join(homedir(), "Library/Caches/ms-playwright");
const shell = process.env.CHROME ?? readdirSync(pw).filter((d) => d.startsWith("chromium_headless_shell")).sort().reverse()
  .flatMap((d) => readdirSync(join(pw, d)).map((s) => join(pw, d, s, "chrome-headless-shell"))).find(existsSync);
const port = 9450 + Math.floor(Math.random() * 100);
const chrome = spawn(shell, [`--remote-debugging-port=${port}`, "--hide-scrollbars", "about:blank"], { stdio: "ignore" });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
let target; for (let i = 0; i < 60 && !target; i++) { await sleep(200); try { target = (await (await fetch(`http://127.0.0.1:${port}/json`)).json()).find((x) => x.type === "page"); } catch {} }
const ws = new WebSocket(target.webSocketDebuggerUrl); await new Promise((r) => ws.addEventListener("open", r, { once: true }));
let id = 0; const pending = new Map();
ws.addEventListener("message", (e) => { const m = JSON.parse(e.data); if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); } });
const send = (method, params = {}) => new Promise((r) => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
await send("Page.enable"); await send("Runtime.enable");
await send("Emulation.setDeviceMetricsOverride", { width: 1920, height: 1080, deviceScaleFactor: 1, mobile: false });

const markSvg = (size) => `<svg viewBox="0 0 64 64" width="${size}" height="${size}" style="overflow:visible">
  <g id="legs">${paths.map((d) => `<path d="${d}" fill="#f0efec"/>`).join("")}</g>
  <circle id="dot" cx="${dotM[1]}" cy="${dotM[2]}" r="${dotM[3]}" fill="${dotM[4]}"/></svg>`;
const html = (kind) => `<!doctype html><html><head><meta charset="utf-8"><style>
@font-face{font-family:G;src:url(data:font/woff2;base64,${grotesk}) format('woff2');font-weight:300 700}
@font-face{font-family:P;src:url(data:font/woff2;base64,${pixel}) format('woff2')}
*{margin:0;box-sizing:border-box} html,body{width:1920px;height:1080px;overflow:hidden}
body{background:radial-gradient(ellipse 70% 60% at 50% 45%,#121a2a 0%,#0a0d14 55%,#07090d 100%);color:#f2f4f8;font-family:G,sans-serif;-webkit-font-smoothing:antialiased}
.wrap{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center}
.lock{display:flex;align-items:center;gap:56px}
.word{font-family:P;font-size:230px;line-height:1;letter-spacing:0.02em}
.acc{color:#3987e5}
</style></head><body>
${kind === "sting" ? `<div class="wrap">${markSvg(340)}</div>` : `<div class="wrap">
  <div class="lock">${markSvg(250)}<div class="word" id="word">NOMAD<span class="acc">.</span></div></div>
  <div id="url" style="font-weight:600;font-size:66px;margin-top:70px">nomad.charlesms.dev</div>
  <div id="built" style="font-weight:400;font-size:40px;margin-top:24px;color:#9aa4b8">Built on NEAR Intents</div></div>`}
<script>
// cubic-bezier(0.22,1,0.36,1), solved for x by Newton steps
function bez(x1, y1, x2, y2) { const cx = 3*x1, bx = 3*(x2-x1)-cx, ax = 1-cx-bx, cy = 3*y1, by = 3*(y2-y1)-cy, ay = 1-cy-by;
  const X = (t) => ((ax*t+bx)*t+cx)*t, Y = (t) => ((ay*t+by)*t+cy)*t, dX = (t) => (3*ax*t+2*bx)*t+cx;
  return (x) => { let t = x; for (let i = 0; i < 8; i++) { const d = dX(t); if (Math.abs(d) < 1e-6) break; t -= (X(t)-x)/d; } return Y(Math.min(1, Math.max(0, t))); }; }
const ease = bez(0.22, 1, 0.36, 1);
const seg = (t, a, b) => Math.min(1, Math.max(0, (t - a) / (b - a)));
const back = (p) => { const c = 1.9; return 1 + (c + 1) * Math.pow(p - 1, 3) + c * Math.pow(p - 1, 2); };
const K = ${JSON.stringify(kind)};
window.renderAt = (t) => {
  const turn = K === "sting" ? [0.0, 0.75] : [0.15, 1.35], pop = K === "sting" ? [0.45, 0.8] : [0.95, 1.35];
  const p = ease(seg(t, ...turn));
  const legs = document.getElementById("legs");
  legs.setAttribute("transform", "rotate(" + (-120 * (1 - p)).toFixed(3) + " 32 32)");
  legs.style.opacity = Math.min(1, seg(t, turn[0], turn[0] + 0.2)).toFixed(3);
  const q = seg(t, ...pop), s = q <= 0 ? 0 : back(q);
  document.getElementById("dot").setAttribute("transform", "translate(32 32) scale(" + s.toFixed(4) + ") translate(-32 -32)");
  if (K === "end") {
    const w = ease(seg(t, 0.75, 1.5)), u = ease(seg(t, 1.2, 1.9)), b = ease(seg(t, 1.45, 2.15));
    const W = document.getElementById("word"); W.style.opacity = w; W.style.transform = "translateX(" + ((1 - w) * -40).toFixed(1) + "px)";
    const U = document.getElementById("url"); U.style.opacity = u; U.style.transform = "translateY(" + ((1 - u) * 24).toFixed(1) + "px)";
    const B = document.getElementById("built"); B.style.opacity = b; B.style.transform = "translateY(" + ((1 - b) * 24).toFixed(1) + "px)";
  }
  return 1;
};
</script></body></html>`;

async function clip(kind, secs, file) {
  await send("Page.navigate", { url: "data:text/html;base64," + Buffer.from(html(kind)).toString("base64") });
  await sleep(500); await send("Runtime.evaluate", { expression: "document.fonts.ready.then(() => 1)", awaitPromise: true });
  const out = join(outDir, file);
  const ff = spawn(FFMPEG, ["-y", "-loglevel", "error", "-f", "image2pipe", "-framerate", "30", "-c:v", "png", "-i", "-",
    "-c:v", "libx264", "-pix_fmt", "yuv420p", "-crf", "15", "-r", "30", out], { stdio: ["pipe", "inherit", "inherit"] });
  const n = Math.round(secs * 30);
  for (let f = 0; f < n; f++) {
    await send("Runtime.evaluate", { expression: `renderAt(${f / 30})` });
    const r = await send("Page.captureScreenshot", { format: "png" });
    const buf = Buffer.from(r.result.data, "base64");
    if (!ff.stdin.write(buf)) await new Promise((r) => ff.stdin.once("drain", r));
  }
  ff.stdin.end(); await new Promise((r) => ff.on("close", r));
  console.log(`wrote ${out}: ${n} frames`);
}
try {
  await clip("sting", 1.0, "logo-sting.mp4");
  await clip("end", 4.0, "logo-end.mp4");
} finally { chrome.kill(); ws.close(); }
process.exit(0);
